import requests
import json

# Search the Isabelle Archive of Formal Proofs for Tarski undefinability
# Let me try to access their website
url = "https://www.isa-afp.org/"
try:
    response = requests.get(url, timeout=10)
    print("Isabelle AFP homepage status:", response.status_code)
    # Look for Tarski or undefinability
    if "Tarski" in response.text or "undefinability" in response.text.lower():
        print("Found references to Tarski/undefinability on homepage")
    else:
        print("No direct references on homepage")
except Exception as e:
    print("Error:", e)

# Try the search/browse pages
url2 = "https://www.isa-afp.org/entries.html"
try:
    response = requests.get(url2, timeout=10)
    print("Entries page status:", response.status_code)
    content = response.text
    if "Tarski" in content:
        print("Found Tarski in entries")
    if "undefinability" in content.lower():
        print("Found undefinability in entries")
    if "Goedel" in content or "Gödel" in content:
        print("Found Gödel in entries")
except Exception as e:
    print("Error:", e)

